import math

def is_prime_power(N, p):
    """Checks if N is a power of prime p, and returns the exponent if true, otherwise None."""
    if N <= 0:
        return None
    if N == 1:
        return 0 # Exponents A, B must be >= 2

    temp = N
    exponent = 0
    while temp > 1:
        if temp % p != 0:
            return None
        temp //= p
        exponent += 1

    return exponent if exponent >= 2 else None

# Search parameters
M_MAX = 15
N_MAX = 15
PRIME_LIST = [2, 5]

found_triples = set()

print(f"Starting systematic search for p={PRIME_LIST} with m, n <= {M_MAX}.")

for m in range(1, M_MAX + 1):
    for n in range(1, N_MAX + 1):
        X = m*m + n
        Y = m + n*n

        for p in PRIME_LIST:
            A = is_prime_power(X, p)
            B = is_prime_power(Y, p)

            if A is not None and B is not None:
                # Both are powers of p, and exponents are >= 2
                triple = (m, n, p)
                if triple not in found_triples:
                    found_triples.add(triple)
                    print(f"Found: ({m}, {n}, {p}). Check: X={X}={p}^{A}, Y={Y}={p}^{B}")

if not found_triples:
    print("No solutions found for p=2 or p=5 up to m, n <= 15.")
else:
    print("\n--- Summary ---")
    for triple in found_triples:
        m, n, p = triple
        print(f"Triple: {triple}")
